def voting_predict(models, x, mode='hard'):
    if mode == 'hard':  # 예측 클래스 다수결
        votes = [m.predict(x) for m in models]
        return max(set(votes), key=votes.count)
    # soft: 클래스별 확률 평균 후 최댓값 선택
    probs = [m.predict_proba(x) for m in models]  # dict
    avg = {c: sum(p[c] for p in probs) / len(probs)
           for c in probs[0]}
    return max(avg, key=avg.get)
